input.command:
cd /home/axel/LeanAlgebraicGeometry-Horizon && python3 - <<'EOF'
import re,pathlib
roots={
 'Algebraic-Jacobian-Challenge-Rebuild':'MainProjects/Algebraic-Jacobian-Challenge-Rebuild',
 'Algebraic-Jacobian-Challenge':'MainProjects/Algebraic-Jacobian-Challenge',
}
for p in pathlib.Path('SubProjects').iterdir():
    if p.is_dir(): roots[p.name]=str(p)
for p in pathlib.Path('SubProjects/RelatedPapersFormalisation').iterdir() if pathlib.Path('SubProjects/RelatedPapersFormalisation').exists() else []:
    if p.is_dir(): roots[p.name]=str(p)
for name,r in sorted(roots.items()):
    rp=pathlib.Path(r)
    tot=0
    for f in rp.rglob('*.lean'):
        if '.lake' in str(f) or 'lake-packages' in str(f): continue
        s=f.read_text(errors='ignore')
        s=re.sub(r'/-.*?-/','',s,flags=re.S); s=re.sub(r'--[^\n]*','',s)
        tot+=len(re.findall(r'\bsorry\b',s))
    tc=list(rp.glob('lean-toolchain'))
    tool=tc[0].read_text().strip() if tc else '-'
    print(f"{name:45s} sorries={tot:4d}  toolchain={tool}")
EOF
